func (s *articleFacadeImpl) CreateArticle(ctx context.Context, request CreateArticleRequest, author user.User) (ArticleView, error) {
    id := uuid.New().String()
    newArticle := request.ToArticle(id, author.ID)
    savedArticle, err := s.articleRepo.Save(ctx, newArticle)
    if err != nil {
        return ArticleView{}, fmt.Errorf("save article: %w", err)
    }
    err = s.tagRepo.SaveAllTags(ctx, savedArticle.Tags)
    if err != nil {
        return ArticleView{}, fmt.Errorf("save tags: %w", err)
    }
    authorProfileView := author.ToOwnProfileView()
    return savedArticle.ToArticleView(authorProfileView, author), nil
}

