func (s *articleFacadeImpl) UpdateArticle(ctx context.Context, request UpdateArticleRequest, slug string, author user.User) (ArticleView, error) {
    articleToUpdate, err := s.articleRepo.FindBySlug(ctx, slug)
    if err != nil {
        return ArticleView{}, fmt.Errorf("find article by slug: %w", err)
    }

    if !articleToUpdate.IsAuthor(author) {
        return ArticleView{}, fmt.Errorf("invalid request: only author can update article")
    }

    s.UpdateUser(request, articleToUpdate)

    savedArticle, err := s.articleRepo.Save(ctx, articleToUpdate)
    if err != nil {
        return ArticleView{}, fmt.Errorf("save article: %w", err)
    }

    return savedArticle.ToAuthorArticleView(author), nil
}

func (s *articleFacadeImpl) DeleteArticle(ctx context.Context, slug string, user user.User) error {
    articleToDelete, err := s.articleRepo.FindBySlug(ctx, slug)
    if err != nil {
        return fmt.Errorf("find article by slug: %w", err)
    }

    if !articleToDelete.IsAuthor(user) {
        return fmt.Errorf("invalid request: only author can delete own article")
    }

    err = s.articleRepo.DeleteBySlug(ctx, slug)
    if err != nil {
        return fmt.Errorf("delete article by slug: %w", err)
    }

    return nil
}

