func (s *articleFacadeImpl) FindArticles(ctx context.Context, tag, authorName, favoritedByUser string, offset int64, limit int, currentUser *user.User) (MultipleArticlesView, error) {
    var favoritedBy *user.User
    if favoritedByUser != "" {
        var err error
        favoritedBy, err = s.userRepo.FindByUsername(ctx, favoritedByUser)
        if err != nil {
            return MultipleArticlesView{}, fmt.Errorf("find favoritedBy user: %w", err)
        }
    }

    var author *user.User
    if authorName != "" {
        var err error
        author, err = s.userRepo.FindByUsername(ctx, authorName)
        if err != nil {
            return MultipleArticlesView{}, fmt.Errorf("find author user: %w", err)
        }
    }

    articles, err := s.articleRepo.FindNewestArticleFilteredBy(ctx, tag, author.ID, favoritedBy, limit, offset)
    if err != nil {
        return MultipleArticlesView{}, fmt.Errorf("find articles: %w", err)
    }

    articleViews := make([]ArticleView, len(articles))
    for i, article := range articles {
        articleViews[i] = mapToArticleView(article, currentUser)
    }

    return toMultipleArticlesView(articleViews), nil
}

func (s *articleFacadeImpl) Feed(ctx context.Context, offset int64, limit int, user user.User) (MultipleArticlesView, error) {
    articles, err := s.articleRepo.FindNewestArticlesByAuthorIds(ctx, user.FollowingIds, offset, limit)
    if err != nil {
        return MultipleArticlesView{}, fmt.Errorf("feed: %w", err)
    }

    var articleViews []ArticleView
    for _, article := range articles {
        articleView := mapToArticleView(article, user)
        articleViews = append(articleViews, articleView)
    }

    return toMultipleArticlesView(articleViews), nil
}

