func (s *articleFacadeImpl) FavoriteArticle(ctx context.Context, slug string, currentUser user.User) (ArticleView, error) {
    article, err := s.articleRepo.FindBySlugOrFail(ctx, slug)
    if err != nil {
        return ArticleView{}, fmt.Errorf("find article by slug: %w", err)
    }

    currentUser.Favorite(article)

    if err := s.userRepo.Save(ctx, currentUser); err != nil {
        return ArticleView{}, fmt.Errorf("save user: %w", err)
    }

    return mapToArticleView(article, currentUser), nil
}



