func (s *articleFacadeImpl) AddComment(ctx context.Context, slug string, content CreateCommentRequest, currentUser user.User) (CommentView, error) {
    article, err := s.articleRepo.FindBySlug(ctx, slug)
    if err != nil {
        return CommentView{}, fmt.Errorf("find article by slug: %w", err)
    }

    comment := content.ToComment(uuid.New().String(), currentUser.ID)
    article.AddComment(comment)

    if err := s.articleRepo.Save(ctx, article); err != nil {
        return CommentView{}, fmt.Errorf("save article: %w", err)
    }

    return comment.ToCommentView(currentUser.ToOwnProfileView()), nil
}


